select brand, category, case when stock_qty >= 429 then 'high' when stock_qty >= 193 then 'mid' else 'low' end as stock_qty_bucket, sum(case when brand = 'Stark' then 1 else 0 end) as stark_count, round((100 * sum(case when brand = 'Initech' then 1 else 0 end)) / count(*), 1) as pct_initech from products where product_name like 'Des%' group by brand, category, case when stock_qty >= 429 then 'high' when stock_qty >= 193 then 'mid' else 'low' end;
